// Classifies a QuarantineStore write failure as a genuine DB/pool/query
// failure (503) vs a business/state error like "already quarantined"/"not
// quarantined" (400) — mirrors DeploymentStore's
// is_deployment_db_error/kDeploymentDbErrorPrefix (discovery_routes.cpp,
// adversarial-review MEDIUM hardening round, 2026-08-12: write routes
// previously collapsed every failure, including genuine outages, to 400).
// Keys off the SHARED constant (quarantine_store.hpp), never a local copy of
// the literal.
bool is_quarantine_db_error(const std::string& err) {
    return err.starts_with(kQuarantineDbErrorPrefix);
}

// ── Lightweight JSON string builder ─────────────────────────────────────
// Produces JSON output strings directly, bypassing nlohmann::json template
// instantiation for construction.  Only ~80 lines vs 23 000 lines of
// template machinery — compiles in milliseconds, not minutes.

void json_escape(std::string& out, std::string_view sv) {
    out.reserve(out.size() + sv.size());
    for (char c : sv) {
        switch (c) {
        case '"':
            out += "\\\"";
            break;
        case '\\':
            out += "\\\\";
            break;
        case '\b':
            out += "\\b";
            break;
        case '\f':
            out += "\\f";
            break;
        case '\n':
            out += "\\n";
            break;
        case '\r':
            out += "\\r";
            break;
        case '\t':
            out += "\\t";
            break;
        default:
            if (static_cast<unsigned char>(c) < 0x20) {
                char hex[8];
                std::snprintf(hex, sizeof(hex), "\\u%04x",
                              static_cast<unsigned int>(static_cast<unsigned char>(c)));
                out += hex;
            } else {
                out += c;
            }
        }
    }
}

/// JSON object builder.  Usage: JObj().add("k",v).add("k2",v2).str()
class JObj {
    std::string buf_;
    int n_ = 0;

    void pre() { buf_ += (n_++ ? ',' : '{'); }
    void key(std::string_view k) {
        pre();
        buf_ += '"';
        json_escape(buf_, k);
        buf_ += "\":";
    }

public:
    JObj() = default;

    JObj& add(std::string_view k, std::string_view v) {
        key(k);
        buf_ += '"';
        json_escape(buf_, v);
        buf_ += '"';
        return *this;
    }
    JObj& add(std::string_view k, const std::string& v) { return add(k, std::string_view(v)); }
    JObj& add(std::string_view k, const char* v) { return add(k, std::string_view(v)); }
    JObj& add(std::string_view k, int64_t v) {
        key(k);
        buf_ += std::to_string(v);
        return *this;
    }
    JObj& add(std::string_view k, int v) { return add(k, static_cast<int64_t>(v)); }
    JObj& add(std::string_view k, double v) {
        key(k);
        buf_ += std::format("{:.2f}", v);
        return *this;
    }
    JObj& add(std::string_view k, bool v) {
        key(k);
        buf_ += v ? "true" : "false";
        return *this;
    }
    /// Embed a pre-serialized JSON fragment (object, array, literal).
    JObj& raw(std::string_view k, std::string_view json) {
        key(k);
        buf_ += json;
        return *this;
    }

    [[nodiscard]] std::string str() const { return n_ ? buf_ + '}' : "{}"; }
};

/// JSON array builder.
class JArr {
    std::string buf_;
    int n_ = 0;

public:
    JArr() = default;

    JArr& add(const JObj& obj) {
        buf_ += (n_++ ? ',' : '[');
        buf_ += obj.str();
        return *this;
    }
    JArr& add(std::string_view s) {
        buf_ += (n_++ ? ',' : '[');
        buf_ += '"';
        json_escape(buf_, s);
        buf_ += '"';
        return *this;
    }
    JArr& add_raw(std::string_view json) {
        buf_ += (n_++ ? ',' : '[');
        buf_ += json;
        return *this;
    }

    [[nodiscard]] std::string str() const { return n_ ? buf_ + ']' : "[]"; }
    [[nodiscard]] int64_t size() const { return n_; }
};

// ── Envelope helpers ────────────────────────────────────────────────────

std::string ok_json(std::string_view data_json) {
    return JObj().raw("data", data_json).raw("meta", R"({"api_version":"v1"})").str();
}

// The legacy bare error_json() helper is retired (#1470): every /api/v1 error
// body now goes through detail::a4_error(res, msg) (code derived from
// res.status) or detail::a4_denial, so it carries correlation_id +
// retry_after_ms per agentic-first §A4.

std::string list_json(std::string_view data_json, int64_t total, int64_t start = 0,
                      int64_t page_size = 50, bool result_truncated_by_cap = false) {
    auto pag_obj = JObj().add("total", total).add("start", start).add("page_size", page_size);
    // Present-only-when-true, matching list_schedules'/query_responses' own
    // result_truncated_by_cap convention: `total` above is the count RETURNED,
    // never asserted as the true total, and a caller must not read an absent
    // key as "definitely complete" vs. "not applicable to this route" -- both
    // read the same (absent), which is the existing convention's own limit.
    if (result_truncated_by_cap)
        pag_obj.add("result_truncated_by_cap", true);
    auto pag = pag_obj.str();
    return JObj()
        .raw("data", data_json)
        .raw("pagination", pag)
        .raw("meta", R"({"api_version":"v1"})")
        .str();
}

// ── PR 4.3 — engine-principal lifecycle route helpers ──────────────────────

// §9 Phase-4 structural denial belt (docs/auth-engine-principals-design.md
// §9): every engine-principal MUTATING route must reject a caller whose own
// session belongs to an engine principal — an engine session must never be
// able to mint/rotate/revoke/transfer engine-principal identities, even if a
// future RBAC misconfiguration somehow granted it Security:Write. Keyed on
// the persisted `principal_kind` FIRST (the durable discriminator, design
// doc §6), with `auth_source=="engine_token"` as a second belt so a future
// second engine authentication path cannot silently bypass a string-keyed
// deny. Returns true (and has already written the 403 A4 body) when the
// caller must stop; false when the session is human and the route may
// proceed.
static bool deny_engine_session(const auth::Session& s, const httplib::Request& req,
                                httplib::Response& res, const RestApiV1::AuditFn& audit,
                                const char* action, const char* target) {
    if (s.principal_kind == "engine" || s.auth_source == "engine_token") {
        // #2466/#2406: surface a dropped denial-audit via Sec-Audit-Failed (the
        // 403 stands — a denial commits no mutation, so it does not fail closed;
        // the header carries the audit-persist gap, matching the route successes).
        // DELIBERATE (adversarial-review K6): the header is kept on this denial
        // even though the caller is the default-deny engine class — the coarse
        // "audit is down" bit it exposes is marginal (during an outage every
        // engine-principal MUTATION already fails closed fleet-wide), keeping
        // Sec-Audit-Failed uniform across every response whose audit dropped is a
        // monitoring virtue, and defenders get the drop server-side regardless via
        // the audit-emit-failed metric + warn log independent of this header.
        (void)detail::emit_behavioral_audit(audit, req, res, action, "denied", target, "",
                                            "engine_session_denied");
        res.status = 403;
        res.set_content(detail::a4_error(res, "engine principals cannot access this endpoint"),
                        "application/json");
        return true;
    }
    return false;
}

// Maps an EnginePrincipalStore/ApiTokenStore `std::expected<..., string>`
// failure message to an HTTP status. The stores are string-typed-error, not
// exception-typed — this keeps the mapping in one place instead of
// re-deriving substring checks at every call site (create/mint/rotate/
// confirm). Store-unavailable / entropy-exhaustion conditions are retryable
// (503); "grace window elapsed" is a genuine state conflict (409, design §7
// — the caller must fall back to an explicit re-mint or the compromise
// runbook, never retry indefinitely); a message this function does NOT
// recognize as one of the store's own hand-authored validation strings is
// classified 503, not 400 (Hermes/governance finding: a swallowed SELECT
// failure inside `read_active_for_principal_on_conn` returns an EMPTY vector
// on error, not a distinguishable error — so `rotate_engine_credential`'s
// "no active credential to rotate — mint one first" and
// `confirm_rotation`'s "no in-flight rotation to confirm" are structurally
// AMBIGUOUS between "genuinely no credential/rotation" and "the read
// silently failed"; treating them as a definitive 400 misleads the operator
// into minting a — possibly REDUNDANT — second credential, which then wedges
// every future rotate. Deliberately unmatched here so they fall through to
// the retryable default instead. Only messages this function can positively
// identify as pure client-input validation (no DB round trip needed to
// produce them, or an unambiguous non-empty-read data-shape fact) get an
// explicit 400 mapping below.
//
// #2404 refinement: this ambiguity is SPECIFIC to the EMPTY-read cases. A
// confirm that reads a NON-empty active set (one credential, or >2, or a
// two-credential pair) is a positive read — see rotation_confirm_state.hpp —
// so those states now carry terminal conflict/client strings (409/400), and
// only the genuinely-empty-or-unrecognized-pair case keeps the retryable "no
// in-flight rotation to confirm".
static int engine_store_error_status(const std::string& err) {
    // Thin dispatch over the shared classifier (engine_store_error_class.hpp)
    // so REST and the MCP twin (mcp_error_for_store_msg) never diverge.
    switch (yuzu::server::detail::classify_engine_store_error(err)) {
    case yuzu::server::detail::EngineStoreErrorClass::ClientValidation:
        return 400;
    case yuzu::server::detail::EngineStoreErrorClass::Conflict:
        return 409;
    case yuzu::server::detail::EngineStoreErrorClass::Transient:
        return 503;
    case yuzu::server::detail::EngineStoreErrorClass::SecretMismatch:
        // #3015: reachable only after the caller cleared every other
        // admission gate — 403, distinct from the 400/409/503 above.
        return 403;
    }
    return 503; // unreachable — all enum cases return above
}

// #2961 round-2 finding (item 4): the store's own error string for the
// resolve_rotation_initiator failure — "rotation confirmation unavailable —
// fall back to revoke" — is the ONLY guidance a machine client (agentic
// worker over REST/MCP) ever sees for this state, and "revoke" alone reads
// as the terminal `DELETE /api/v1/engine-principals/{id}` route, which
// destroys BOTH credentials plus the principal. There is no MCP twin of
// `DELETE /api/v1/tokens/{token_id}` — the actual safe remedy is
// per-credential revoke on the SPECIFIC untrusted token. Named here, once,
// as a structured `remediation` field rather than folded into the message
// string itself, so a client that reads `remediation` gets the safe route
// without string-parsing the error message.
constexpr std::string_view kRotationConfirmUnavailableRemediation =
    "revoke the specific untrusted credential via DELETE /api/v1/tokens/{token_id} "
    "(there is no per-credential revoke via the MCP engine-principal tools) — "
    "never DELETE /api/v1/engine-principals/{id}, which is terminal and destroys "
    "both credentials plus the principal";

// Remediation text for a store confirm-rotation error, or empty for every
// other error class (those already carry an actionable message on their
// own). Shared by both confirm routes (engine + human arm) so the two
// transports can never diverge on wording, same rationale as
// classify_engine_store_error's own single-chokepoint contract.
static std::string_view confirm_rotation_error_remediation(const std::string& err) {
    if (err.find("rotation confirmation unavailable") != std::string::npos)
        return kRotationConfirmUnavailableRemediation;
    return {};
}

// AccessReviewStore (Periodic Access Reviews, SOC 2 CC6.2) error mapping —
// per access_review_store.hpp's documented contract, `get_campaign` /
// `record_attestation` / `close_campaign` signal "no such campaign / no such
// frozen grant / campaign not open" via an `unexpected` payload PREFIXED
// `"not_found: "` (machine-checkable). That prefix maps to 404; every other
// `unexpected` (a genuine write/read failure — lease timeout, query error) is
// a transient 503, never a 400 — the caller did nothing wrong, the store did.
//
// Contract pin: this classifier is binary (not_found: -> 404, else -> 503)
// because every route above pre-validates its own inputs (title/decision/
// principal_type/principal_id/role_name all required) BEFORE ever calling
// into the store, so the store's own input-validation error strings (e.g.
// "title cannot be empty", "decision must be...") never actually reach this
// function today — they would fall into the `else -> 503` arm, which is
// wrong (client error, not a transient failure). Callers MUST keep
// pre-validating those fields. If a future code path calls into
// AccessReviewStore without pre-validating, add a machine-checkable
// `bad_request:` prefix to that store error and a 400 arm here (and in the
// MCP twin mcp_error_for_access_review_msg in mcp_server.cpp) rather than
// letting it fall through to 503.
static int access_review_error_status(const std::string& err) {
    return err.starts_with("not_found:") ? 404 : 503;
}

// SoftwareDeploymentStore error classifier — mirrors discovery_routes.cpp's
// is_deployment_db_error (DeploymentStore/ADR-0043): the majority of a
// route's `unexpected` values here are caller-input validation or
// not-found/wrong-state business errors (400 territory, matching how
// DeploymentStore's own REST routes classify — see cancel_job's route,
// which 400s "job not found" too, not 404; none of these store methods have
// a REST get-by-id twin that would need the separate nullopt-vs-unexpected
// 404 split). Keys off the SHARED constant (software_deployment_store.hpp),
// never a local copy of the literal.
static int sw_deploy_error_status(const std::string& err) {
    return err.starts_with(kSwDeployDbErrorPrefix) ? 503 : 400;
}

// Never echoes a genuine DB/lease failure's raw text to the client — it can
// embed PQerrorMessage() fragments (schema/constraint/DETAIL names, and on a
// connection-phase failure occasionally a host:port) that are internal
// implementation detail, not information the caller needs (gov Gate 2
// security-guardian MEDIUM). Logs the real error server-side and returns a
// generic constant instead, matching DeploymentStore's discovery_routes.cpp
// precedent (`is_deployment_db_error` branch). A validation/business-rule
// error (never carries the prefix) is safe to echo verbatim — it's
// operator-authored request feedback, not database internals.
static std::string sw_deploy_client_message(const char* op, const std::string& err) {
    if (err.starts_with(kSwDeployDbErrorPrefix)) {
        spdlog::error("{}: {}", op, err);
        return "service unavailable";
    }
    return err;
}

// LicenseStore (docs/adr/0048-...md) error mapping — three-way, unlike
// access_review_error_status's binary shape: LicenseStore's own methods still validate some
// inputs internally (e.g. "license key already activated", "organization cannot be empty")
// rather than pre-validating in the route, so a THIRD bucket is needed for those. `not_found: `
// (license_store.hpp's machine-checkable idiom) -> 404; `kLicenseDbErrorPrefix` (a genuine
// DB/lease failure) -> 503; anything else (validation / business-rule error) -> 400. Preserves
// the pre-migration DELETE route's 404-for-missing-id behavior that a DeploymentStore-style
// binary (prefix vs else) classifier would have regressed to 400 (ADR-0048 "Considered and
// rejected").
static int license_error_status(const std::string& err) {
    if (err.starts_with("not_found:"))
        return 404;
    if (err.starts_with(yuzu::server::kLicenseDbErrorPrefix))
        return 503;
    return 400;
}

// DeviceTokenStore (docs/adr/0052-...md) error mapping — same three-way shape as
// license_error_status: `not_found: ` (revoke_token's missing-id case) -> 404,
// `kDeviceTokenDbErrorPrefix` (a genuine DB/lease failure) -> 503, anything else
// (create_token's validation errors) -> 400. Preserves the pre-migration DELETE route's 404 for
// a missing token_id, which a binary (prefix-only) classifier would have regressed to 400.
static int device_token_error_status(const std::string& err) {
    if (err.starts_with("not_found:"))
        return 404;
    if (err.starts_with(yuzu::server::kDeviceTokenDbErrorPrefix))
        return 503;
    return 400;
}

// Never echoes a genuine DB/lease failure's raw text to the client (mirrors
// sw_deploy_client_message — see its comment for the full rationale: PQerrorMessage() fragments
// are internal implementation detail, not caller-actionable feedback). A not_found/validation
// error (never carries the prefix) is safe to echo verbatim.
static std::string device_token_client_message(const char* op, const std::string& err) {
    if (err.starts_with(yuzu::server::kDeviceTokenDbErrorPrefix)) {
        spdlog::error("{}: {}", op, err);
        return "service unavailable";
    }
    return err;
}

// A present-but-wrong-typed JSON body field (e.g. {"title": 5}) must degrade
// to the default rather than throw nlohmann's type_error.302 out of
// `body.value(key, default)` (-> uncaught -> 500). Mirrors MCP's
// param_str (mcp_server.cpp) so the REST and MCP twins agree on the same
// wrong-typed-field -> clean-400 behavior.
static std::string access_review_str_field(const nlohmann::json& body, const char* key,
                                            const char* def = "") {
    if (body.contains(key) && body[key].is_string())
        return body[key].get<std::string>();
    return def;
}

// Render a live plugin output into the JSON `data` object for /dex/devices/{id}/live.
// The wire-format parsing (kind table + field extraction) is shared with the
// dashboard HTML path via live_kinds.hpp so the two cannot drift (governance S2);
// this only maps the parsed fields to JSON. The agent sanitizes '|'/CR/LF out of
// every field, and the parser is bounds-safe on any input regardless.
std::string live_result_json(const std::string& kind, const std::string& output) {
    if (kind == "uptime") {
        const auto u = live::parse_uptime(output);
        JObj o;
        o.add("kind", "uptime");
        if (u.display)
            o.add("uptime_display", *u.display);
        if (u.seconds)
            o.add("uptime_seconds", *u.seconds);
        return o.str();
    }
    JArr procs;
    for (const auto& p : live::parse_processes(output))
        procs.add(
            JObj().add("pid", p.pid).add("name", p.name).add("sha256", p.sha256).add("path", p.path));
    return JObj().add("kind", "processes").raw("processes", procs.str()).str();
}

// Bound concurrent /api/v1/dex/devices/{id}/live polls (UP-1/2/3): each call pins
// an httplib worker for up to ~20s, so an unbounded burst (or SSE pre-pressure)
// would starve the dashboard, REST and the health probes. The cap is a whole-server
// in-flight budget held strictly below the worker pool; over-budget callers get 429
// + retry_after_ms instead of dispatching a command they can't wait for. RAII so
// EVERY exit path (429/400/502/503/504/200) releases the slot — a leaked slot would
// permanently shrink capacity. `acquired` records whether we were within budget.
class LiveInflightGuard {
public:
    // `gauge` (optional) mirrors the current in-flight depth for observability —
    // updated to the live atomic value on acquire and release so an operator can see
    // saturation approaching the cap (sre S1). Borrowed; the registry outlives the
    // handler.
    explicit LiveInflightGuard(yuzu::Gauge* gauge = nullptr) : gauge_(gauge) {
        const int cap = detail::live_max_inflight().load(std::memory_order_relaxed);
        acquired_ = inflight_.fetch_add(1, std::memory_order_acq_rel) < cap;
        if (gauge_)
            gauge_->set(inflight_.load(std::memory_order_relaxed));
    }
    ~LiveInflightGuard() {
        inflight_.fetch_sub(1, std::memory_order_acq_rel);
        if (gauge_)
            gauge_->set(inflight_.load(std::memory_order_relaxed));
    }
    LiveInflightGuard(const LiveInflightGuard&) = delete;
    LiveInflightGuard& operator=(const LiveInflightGuard&) = delete;
    bool acquired() const { return acquired_; }

private:
    yuzu::Gauge* gauge_{nullptr};
    static inline std::atomic<int> inflight_{0};
    bool acquired_{false};
};

